<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Program,Department};use Illuminate\Http\Request;use Illuminate\Support\Str;class ProgramController extends Controller{public function index(){return view('admin.programs.index',['items'=>Program::with('department')->orderBy('sort')->paginate(30)]);}public function create(){return $this->form(new Program);}public function store(Request $r){Program::create($this->data($r));return redirect()->route('admin.programs.index')->with('ok','Программа создана');}public function edit(Program $program){return $this->form($program);}public function update(Request $r,Program $program){$program->update($this->data($r));return redirect()->route('admin.programs.index')->with('ok','Сохранено');}public function destroy(Program $program){$program->delete();return back();}private function form($item){return view('admin.programs.form',['item'=>$item,'departments'=>Department::orderBy('sort')->get()]);}private function data(Request $r){$d=$r->validate(['name'=>'required|max:255','department_id'=>'nullable|exists:departments,id','description'=>'nullable','duration'=>'nullable|max:100','age'=>'nullable|max:100','sort'=>'nullable|integer']);$d['slug']=Str::slug($r->input('slug')?:$d['name']);$d['is_active']=$r->boolean('is_active');return $d;}}